"use client";

import { useState } from "react";
import { Menu, Search, Globe } from "lucide-react";
import { useTheme } from "@/providers";
import { storefrontNav } from "@/config";
import { MobileNav } from "./mobile-nav";

type StorefrontHeaderProps = {
  slogan?: string;
  backgroundImage?: string;
  logo?: string;
  companyName?: string;
};

export function StorefrontHeader({
  slogan,
  backgroundImage,
  logo,
  companyName,
}: StorefrontHeaderProps) {
  const { tokens } = useTheme();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);

  return (
    <header className="relative">
      {/* Slogan banner with background image */}
      <div
        className="relative flex items-center justify-center px-4 py-4 "
        style={{
          background: backgroundImage
            ? `url(${backgroundImage}) center/cover no-repeat`
            : tokens.secondary,
          color: backgroundImage ? "#fff" : tokens.secondaryForeground,
        }}
      >
        {/* Overlay for readability when image is present */}
        {backgroundImage && (
          <div
            aria-hidden="true"
            className="absolute inset-0 bg-black/40"
          />
        )}
        <div className="relative z-10 text-center">
          <h1
            className="text-sm font-bold tracking-tight md:text-lg "
            style={{ fontFamily: tokens.fontHeading }}
          >
            {slogan || companyName || "سنگ طبیعی"}
          </h1>
        </div>
      </div>

      {/* Navbar */}
      <nav
        className="sticky top-0 z-30 border-b"
        style={{
          background: tokens.background,
          borderColor: tokens.border,
          color: tokens.foreground,
        }}
        aria-label="Main navigation"
      >
        <div className="mx-auto flex max-w-7xl items-center justify-between gap-4 px-4 py-3 sm:px-6 lg:px-8">
          {/* Right side: hamburger + logo */}
          <div className="flex items-center gap-3">
            {/* Hamburger (mobile only) */}
            <button
              type="button"
              onClick={() => setMobileOpen(true)}
              aria-label="باز کردن منو"
              className="p-2 rounded-md hover:bg-muted transition-colors lg:hidden"
            >
              <Menu className="h-5 w-5" />
            </button>

            {/* Logo */}
            <a href="/" className="flex items-center gap-2">
              {logo ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={logo}
                  alt={companyName || "لوگو"}
                  className="h-8 w-auto object-contain"
                />
              ) : (
                <span
                  className="text-lg font-bold tracking-tight"
                  style={{ color: tokens.primary, fontFamily: tokens.fontHeading }}
                >
                  {companyName || "سنگ"}
                </span>
              )}
            </a>
          </div>

          {/* Center: desktop nav links */}
          <div className="hidden items-center gap-1 lg:flex">
            {storefrontNav.map((item) => (
              <a
                key={item.href}
                href={item.href}
                className="rounded-md px-3 py-2 text-sm font-medium text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                {item.title}
              </a>
            ))}
          </div>

          {/* Left side: search + language */}
          <div className="flex items-center gap-2">
            {/* Search */}
            <div className="relative hidden sm:block">
              <Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <input
                type="search"
                placeholder="جستجو..."
                aria-label="جستجو"
                className="w-40 rounded-md border bg-transparent py-2 pl-3 pr-9 text-sm transition-all focus:w-56 focus:outline-none focus:ring-2 lg:w-48"
                style={{
                  borderColor: tokens.border,
                  color: tokens.foreground,
                }}
              />
            </div>

            {/* Mobile search toggle */}
            <button
              type="button"
              onClick={() => setSearchOpen(!searchOpen)}
              aria-label="جستجو"
              className="p-2 rounded-md hover:bg-muted transition-colors sm:hidden"
            >
              <Search className="h-5 w-5" />
            </button>

            {/* Language switch */}
            <button
              type="button"
              aria-label="تغییر زبان"
              className="flex items-center gap-1 rounded-md px-2 py-2 text-sm font-medium hover:bg-muted transition-colors"
            >
              <Globe className="h-4 w-4" />
              <span className="hidden sm:inline">فا</span>
            </button>
          </div>
        </div>

        {/* Mobile search bar (expanded) */}
        {searchOpen && (
          <div className="border-t px-4 py-3 sm:hidden" style={{ borderColor: tokens.border }}>
            <div className="relative">
              <Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <input
                type="search"
                placeholder="جستجو..."
                aria-label="جستجو"
                autoFocus
                className="w-full rounded-md border bg-transparent py-2 pl-3 pr-9 text-sm focus:outline-none focus:ring-2"
                style={{
                  borderColor: tokens.border,
                  color: tokens.foreground,
                }}
              />
            </div>
          </div>
        )}
      </nav>

      {/* Mobile drawer */}
      <MobileNav
        open={mobileOpen}
        onClose={() => setMobileOpen(false)}
        items={storefrontNav}
        slogan={slogan}
      />
    </header>
  );
}